import{_ as a,o as t,c as s,a4 as n}from"./chunks/framework.DpieW3qv.js";const u=JSON.parse('{"title":"Smartsheet Wireframe Guide","description":"","frontmatter":{"title":"Smartsheet Wireframe Guide"},"headers":[],"relativePath":"guides/ecomm-workflow.md","filePath":"guides/ecomm-workflow.md","lastUpdated":null}'),r={name:"guides/ecomm-workflow.md"};function i(d,e,l,o,p,h){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="smartsheet-wireframe-guide" tabindex="-1">Smartsheet Wireframe Guide <a class="header-anchor" href="#smartsheet-wireframe-guide" aria-label="Permalink to &quot;Smartsheet Wireframe Guide&quot;">​</a></h1><p>This guide is for the Ecomm team who manages campaign wireframes in Smartsheet.</p><h2 id="your-role" tabindex="-1">Your Role <a class="header-anchor" href="#your-role" aria-label="Permalink to &quot;Your Role&quot;">​</a></h2><p>You own the wireframe. Producers pull your data, build it, preview it, then push to staging.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                         Workflow                             │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│   Ecomm Team                    Web Producer                 │</span></span>
<span class="line"><span>│   ──────────                    ────────────                 │</span></span>
<span class="line"><span>│   ┌──────────────┐              ┌──────────────┐            │</span></span>
<span class="line"><span>│   │  Smartsheet  │  ─────────&gt;  │  This Tool   │            │</span></span>
<span class="line"><span>│   │  Wireframe   │              │              │            │</span></span>
<span class="line"><span>│   └──────────────┘              └──────┬───────┘            │</span></span>
<span class="line"><span>│                                        │                     │</span></span>
<span class="line"><span>│                                        v                     │</span></span>
<span class="line"><span>│                                 ┌──────────────┐            │</span></span>
<span class="line"><span>│                                 │    SFCC      │            │</span></span>
<span class="line"><span>│                                 │   Website    │            │</span></span>
<span class="line"><span>│                                 └──────────────┘            │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><h2 id="what-you-control" tabindex="-1">What You Control <a class="header-anchor" href="#what-you-control" aria-label="Permalink to &quot;What You Control&quot;">​</a></h2><p>The wireframe in Smartsheet contains all campaign data:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Refresh Date</strong></td><td>When content goes live</td><td>2026-02-03</td></tr><tr><td><strong>Refresh Number</strong></td><td>Which refresh (r1, r2, r3)</td><td>r1</td></tr><tr><td><strong>Action</strong></td><td>What to do</td><td>LAUNCH, UPDATE, REMOVE</td></tr><tr><td><strong>Zone</strong></td><td>Page area</td><td>1T/A1, 2T, 2L/A2</td></tr><tr><td><strong>Content</strong></td><td>Headlines, copy, links</td><td>&quot;Shop New Arrivals&quot;</td></tr><tr><td><strong>Destination ID</strong></td><td>Link target</td><td>catl00009, /sale</td></tr><tr><td><strong>IPID</strong></td><td>Tracking ID</td><td>loft_hp_hero_012626</td></tr><tr><td><strong>Images</strong></td><td>Asset URLs</td><td>/images/banner.jpg</td></tr></tbody></table><h2 id="action-values" tabindex="-1">Action Values <a class="header-anchor" href="#action-values" aria-label="Permalink to &quot;Action Values&quot;">​</a></h2><p>Use these values in the Action column:</p><table tabindex="0"><thead><tr><th>Action</th><th>When to Use</th><th>Result</th></tr></thead><tbody><tr><td><strong>LAUNCH</strong></td><td>New content</td><td>Creates new asset</td></tr><tr><td><strong>UPDATE</strong></td><td>Change existing</td><td>Updates asset content</td></tr><tr><td><strong>REMOVE</strong></td><td>Delete content</td><td>Removes asset from SFCC</td></tr><tr><td><strong>NO_CHANGE</strong></td><td>Keep as-is</td><td>No processing needed</td></tr></tbody></table><h2 id="switching-to-smartsheet" tabindex="-1">Switching to Smartsheet <a class="header-anchor" href="#switching-to-smartsheet" aria-label="Permalink to &quot;Switching to Smartsheet&quot;">​</a></h2><p>The web producer switches to Smartsheet via:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>They choose <strong>Smartsheet</strong> as the data source in the wizard. They need <code>SMARTSHEET_API_KEY</code> in <code>.env</code> and the sheet ID set via <code>make setup</code> (first time only). To switch back to local Excel, run <code>make setup</code> again and choose <strong>Local Excel file</strong>.</p><h2 id="when-data-gets-pulled" tabindex="-1">When Data Gets Pulled <a class="header-anchor" href="#when-data-gets-pulled" aria-label="Permalink to &quot;When Data Gets Pulled&quot;">​</a></h2><p>The web producer runs:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Git sync + fetch wireframe data + auto-build + status dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Preview HTML for a specific date (auto-builds if stale)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>make pull</code> reads your Smartsheet (or Excel file), creates local JSON files, and auto-builds new dates. The producer then picks a date from the interactive status hub. When using Smartsheet, <code>make pull CONVERT=1</code> fetches the latest sheet and converts it to Excel format.</p><h2 id="what-happens-next" tabindex="-1">What Happens Next <a class="header-anchor" href="#what-happens-next" aria-label="Permalink to &quot;What Happens Next&quot;">​</a></h2><p>After you update the wireframe:</p><ol><li>Web producer runs <code>make pull</code> — fetches the latest data, auto-builds new dates, and sees the dashboard</li><li>Producer runs <code>make preview</code> — builds if stale and previews HTML from templates</li><li>Producer runs <code>make push</code> — validates data quality and syncs to SFCC staging (auto-generates email and prints replicate steps)</li><li>After QA, <code>make replicate</code> — manual replication to production</li></ol><h2 id="making-updates" tabindex="-1">Making Updates <a class="header-anchor" href="#making-updates" aria-label="Permalink to &quot;Making Updates&quot;">​</a></h2><h3 id="same-day-updates" tabindex="-1">Same-Day Updates <a class="header-anchor" href="#same-day-updates" aria-label="Permalink to &quot;Same-Day Updates&quot;">​</a></h3><p>If you need to change content for today:</p><ol><li>Update the wireframe in Smartsheet</li><li>Let the web producer know</li><li>They re-fetch and re-sync</li></ol><h3 id="future-updates" tabindex="-1">Future Updates <a class="header-anchor" href="#future-updates" aria-label="Permalink to &quot;Future Updates&quot;">​</a></h3><p>Plan ahead by adding rows for future dates. The tool only processes dates you specify.</p><h3 id="emergency-updates" tabindex="-1">Emergency Updates <a class="header-anchor" href="#emergency-updates" aria-label="Permalink to &quot;Emergency Updates&quot;">​</a></h3><p>For urgent changes, the web producer can directly edit the JSON files without waiting for a Smartsheet update.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mistake</th><th>Problem</th><th>Fix</th></tr></thead><tbody><tr><td>Wrong action</td><td>LAUNCH creates duplicates</td><td>Use UPDATE for existing</td></tr><tr><td>Missing date</td><td>Content not found</td><td>Ensure date format is correct</td></tr><tr><td>Bad links</td><td>Broken on site</td><td>Verify URLs before adding</td></tr><tr><td>Empty fields</td><td>Template errors</td><td>Fill all required fields</td></tr></tbody></table><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>The tool validates your data before syncing:</p><ul><li>Required fields present</li><li>URLs are valid format</li><li>Dates are parseable</li><li>Actions are recognized</li></ul><p>Errors appear in the terminal with specific row/field info.</p><h2 id="questions" tabindex="-1">Questions? <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Who to Ask</th></tr></thead><tbody><tr><td>Smartsheet access</td><td>Your team lead</td></tr><tr><td>Template changes</td><td>Development team</td></tr><tr><td>Sync issues</td><td>Web producer</td></tr><tr><td>Content questions</td><td>Marketing team</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/excel/wireframe-format.html">Wireframe Format</a> — Field specifications</li><li><a href="/ocapi-docs.github.io/guides/quick-start.html">Quick Start</a> — How the tool works</li><li><a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer Guide</a> — Full producer daily guide</li></ul>`,40)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
